examples.code:
A = magic(3);
[Q, R] = qr(A);
[Q1, R1] = qrdelete(Q, R, 2);
norm(Q1*R1 - A(:, [1 3])) < 1e-10

A = [1 2; 3 4];
B = [5 6; 7 8];
[AA, BB, Q, Z] = qz(A, B);
norm(Q*A*Z - AA) < 1e-10
sort(eig(A, B))'

A = [0 1; -1 0];
[U, T] = schur(A);
[U2, T2] = rsf2csf(U, T);
diag(T2).'
norm(U2*T2*U2' - A) < 1e-12

A = [1 2; 3 4];
[U, T] = schur(A);
norm(U*T*U' - A) < 1e-12
sort(diag(T))'

A = [4 1; 2 3; 0 5];
s = svd(A)
[U, S, V] = svd(A, 'econ');
size(U)
norm(U*S*V' - A) < 1e-12

A = magic(3);
[U, S, V] = svd(A, 'econ');
d = [1; 2; 3];
s1 = svdappend(U, S, V, d)'
s2 = svd([A d])'

A = magic(4);
[U, S, V] = svdsketch(A);
size(S)
norm(U*S*V' - A) < 1e-6
